_WIN_NO_WINDOW = subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0


def _fmt_eta(seconds: float) -> str:
    """Format a number of seconds into a human-readable ETA string, e.g. '~2m 30s'."""
    if seconds <= 0:
        return ""
    s = int(seconds)
    if s < 60:
        return f"~{s}s"
    m, s = divmod(s, 60)
    if m < 60:
        return f"~{m}m {s:02d}s"
    h, m = divmod(m, 60)
    return f"~{h}h {m:02d}m"


def _fmt_duration(seconds: float) -> str:
    """Format elapsed seconds into a compact duration string, e.g. '2m 30s'."""
    if seconds <= 0:
        return ""
    s = int(seconds)
    if s < 60:
        return f"{s}s"
    m, s = divmod(s, 60)
    if m < 60:
        return f"{m}m {s:02d}s"
    h, m = divmod(m, 60)
    return f"{h}h {m:02d}m"

